//! Immutable Machin enclosure, loaded without numeric work or precision caches.

use std::sync::LazyLock;

use super::{Ball, Binary, Integer};

const PRECISION: u32 = 4096;
// Exact dyadics from Machin's identity evaluated at PRECISION + 32 guard bits,
// then outward rounded to PRECISION. The independent recomputation below checks
// both mantissas, including the radius rather than only familiar leading digits.
const MID: &str = "";
const RADIUS: &str = "";

static VALUE: LazyLock<Ball> = LazyLock::new(|| Ball {
    mid: Binary::from_integer(Integer::parse(MID).expect("stored pi midpoint")).mul_pow2(-4094),
    rad: Binary::from_integer(Integer::parse(RADIUS).expect("stored pi radius")).mul_pow2(-8191),
    precision: PRECISION,
});

pub(super) fn at(precision: u32) -> Ball {
    if precision <= PRECISION {
        VALUE.with_precision(precision)
    } else {
        super::pi(precision, None).expect("unbounded pi enclosure")
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{Rational, with_operation_budget};

    #[test]
    fn stored_pi_digits_match_the_independent_machin_series() {
        let reference = super::super::pi(PRECISION, None).unwrap();
        assert_eq!(VALUE.mid(), reference.mid());
        assert_eq!(VALUE.rad(), reference.rad());
        let tighter = super::super::pi(PRECISION + 64, None).unwrap();
        for precision in [1, 2, 53, 128, 255, 256, 1024, PRECISION] {
            let value = at(precision);
            assert!(value.lo() <= tighter.lo());
            assert!(value.hi() >= tighter.hi());
        }
    }

    #[test]
    fn stored_pi_truncation_is_work_free() {
        let (_, work) = with_operation_budget(0, || {
            for precision in [1, 128, 192, PRECISION] {
                at(precision);
            }
        });
        assert_eq!(work.used, 0);
        assert!(!work.exhausted);
    }

    #[test]
    fn precision_beyond_the_constant_has_a_finer_proven_enclosure() {
        let precision = PRECISION + 64;
        let value = at(precision);
        let reference = super::super::pi(precision + 64, None).unwrap();
        assert!(value.lo() <= reference.lo());
        assert!(value.hi() >= reference.hi());
        assert!(&value.hi() - &value.lo() < Rational::one().mul_pow2(-i64::from(precision - 8)));
    }
}
